using System.IO;
using UnityEditor;

namespace Palace.EditorTools
{
    /// <summary>
    /// The painted art (tables, cards, cosmetics and the country flags) is generated by
    /// Palace > Setup > 2 - Generate Art. If it hasn't been run yet, or is out of date (no flags),
    /// this offers to run it when the project opens, so nobody plays with missing cosmetics.
    /// Asks once per Unity session.
    /// </summary>
    [InitializeOnLoad]
    public static class PalaceArtCheck
    {
        private const string AskedKey = "Palace.ArtCheckAsked";

        static PalaceArtCheck()
        {
            if (UnityEngine.Application.isBatchMode) return;
            EditorApplication.delayCall += Check;
        }

        private static void Check()
        {
            if (SessionState.GetBool(AskedKey, false) || EditorApplication.isPlayingOrWillChangePlaymode) return;
            SessionState.SetBool(AskedKey, true);

            bool library = File.Exists(PalaceArtGenerator.LibraryPath);
            bool flags = File.Exists(PalaceArtGenerator.ArtFolder + "/flag_back_chile.png"); // the newest flags
            if (library && flags) return;

            bool go = EditorUtility.DisplayDialog("Palace: generate the art?",
                "The painted art hasn't been generated yet (or is missing the newest items, such as the country flags).\n\n" +
                "Without it the table is plain and the Customise screen is empty.\n\n" +
                "Generate it now? It takes a few minutes (there are 42 flag tables to paint).",
                "Generate now", "Later");
            if (go) PalaceArtGenerator.GenerateAll();
        }
    }
}
